// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testRegression_property() public {
        vm.deal(address(this), 1 ether);
        (bool ok1,) = address(c).call{value: 1 ether}("");
        assertTrue(ok1);
        assertEq(c.depositsCount(), 1);
        assertEq(address(c).balance, 1 ether);

        address target = address(new RevertOnData());

        bool ok2;
        try c.sendMoney(target, 0.5 ether, hex"deadbeef") {
            ok2 = true;
        } catch {
            ok2 = false;
        }
        assertTrue(ok2);
        assertEq(c.depositsCount(), 1);
        assertEq(address(c).balance, 1 ether);
    }
}

contract RevertOnData {
    fallback(bytes calldata data) external payable returns (bytes memory) {
        if (data.length > 0) {
            revert("data not empty");
        }
        return "";
    }
}
